// Simplified from PHPMailer mailSend(), pre-5.2.18 (CVE-2016-10033).
public function mailSend($header, $body) {
    $sender = $this->Sender;                 // taken from the From address
    if ($sender != '') {
        // Pass the envelope sender to sendmail via -f.
        $params = sprintf('-oi -f%s', escapeshellcmd($sender));
        mail($this->to, $this->subj, $body, $header, $params);
    }
}

